#!/usr/bin/env python3
"""Unit tests for the profile SVG generators (stdlib unittest only).

Everything here runs on SYNTHETIC fixture data inside temp directories.
Test artifacts are never written to assets/ and never published — the
network-dependent functions (api_get, graphql, the snk engine itself) are
intentionally NOT covered here; they are exercised by the GitHub Actions
runs and by the browser checks described in docs/profile-maintenance.md.

Snake engine note: the snake is generated by Platane/snk (svg-only) in the
workflow; this suite covers OUR code around it — the panel theming script,
the banner generator, the stats cards, and the file/README/workflow
reference consistency (the old custom snake engine tests were retired
together with gen_snake_svg.py when the engine migrated).

Run:  python .github/scripts/test_generators.py
"""
import os
import re
import sys
import tempfile
import unittest
from datetime import datetime, timezone
from xml.dom import minidom

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.abspath(os.path.join(HERE, "..", ".."))
sys.path.insert(0, HERE)

import gen_stats_svg as stats        # noqa: E402
import make_banners as banners       # noqa: E402
import theme_snake_svg as theme      # noqa: E402


# ----------------------------------------------------------------- helpers --
def check_smil(doc, testcase):
    """values/keyTimes counts match, times strictly increase, span [0, 1]."""
    for a in (doc.getElementsByTagName("animate") +
              doc.getElementsByTagName("animateTransform")):
        vals = a.getAttribute("values").split(";")
        kts = a.getAttribute("keyTimes").split(";")
        if not a.getAttribute("values") and not a.getAttribute("keyTimes"):
            continue                       # from/to animations have neither
        if not kts or not kts[0]:
            continue
        testcase.assertEqual(len(vals), len(kts),
                             "count mismatch on %s" % a.getAttribute("attributeName"))
        kt = [float(x) for x in kts]
        for i in range(len(kt) - 1):
            testcase.assertLess(kt[i], kt[i + 1], "non-monotonic keyTimes")
        if a.getAttribute("calcMode") == "discrete":
            testcase.assertAlmostEqual(kt[0], 0.0)
        else:
            testcase.assertAlmostEqual(kt[0], 0.0)
            testcase.assertAlmostEqual(kt[-1], 1.0)


def texts_of(doc):
    return " ".join(t.firstChild.nodeValue for t in doc.getElementsByTagName("text")
                    if t.firstChild)


SNK_FIXTURE = (
    '<svg xmlns="http://www.w3.org/2000/svg" width="824" height="134" '
    'viewBox="0 0 824 134"><style>.c{fill:#111}</style>'
    '<rect class="c" width="12" height="12"/></svg>'
)


# ------------------------------------------------------------------ banners --
class BannerTests(unittest.TestCase):
    def setUp(self):
        self.anim = banners.build(animate=True)
        self.stat = banners.build(animate=False)

    def test_valid_xml_with_identity_text(self):
        for svg in (self.anim, self.stat):
            doc = minidom.parseString(svg)
            self.assertEqual(doc.documentElement.getAttribute("viewBox"),
                             "0 0 %d %d" % (banners.W, banners.H))
            texts = texts_of(doc)
            self.assertIn("Sohrab Iranpak", texts)
            self.assertIn("R&D Software Engineer", texts)
        self.assertIn("R&amp;D", self.anim)          # XML-safe ampersand

    def test_no_scripts_no_foreign_objects_no_external_refs(self):
        for svg in (self.anim, self.stat):
            doc = minidom.parseString(svg)
            self.assertEqual(doc.getElementsByTagName("script"), [])
            self.assertEqual(doc.getElementsByTagName("foreignObject"), [])
            self.assertNotIn("http://", re.sub(r'xmlns="[^"]*"|xmlns:[a-z]+="[^"]*"',
                                               "", svg))
            self.assertNotIn("<img", svg)
            self.assertNotIn("url(http", svg)

    def test_animated_has_rain_static_has_none(self):
        doc = minidom.parseString(self.anim)
        tf = doc.getElementsByTagName("animateTransform")
        self.assertGreater(len(tf), 20)              # one per rain column
        for a in tf:
            self.assertEqual(a.getAttribute("repeatCount"), "indefinite")
            self.assertTrue(a.getAttribute("begin").startswith("-"),
                            "negative begin required: rain visible at t=0")
        check_smil(doc, self)
        sdoc = minidom.parseString(self.stat)
        self.assertEqual(sdoc.getElementsByTagName("animateTransform"), [])
        self.assertEqual(sdoc.getElementsByTagName("animate"), [])

    def test_rain_loops_without_gap(self):
        """Each stream must start fully above and end fully below the canvas."""
        specs = banners.build_columns(banners.Random(banners.SEED))
        ty_rng = banners.Random(banners.SEED + 1)
        checked = 0
        for spec in specs:
            g = banners.render_column(spec, True, ty_rng)
            m = re.search(r'from="0 ([-\d.]+)" to="0 ([-\d.]+)"', g)
            self.assertIsNotNone(m, "rain column missing from/to animation")
            frm, to = float(m.group(1)), float(m.group(2))
            stream_h = (spec["n"] - 1) * banners.GLYPH_H + banners.GLYPH_SIZE
            self.assertLessEqual(frm + stream_h, 0.001,
                                 "stream starts inside the canvas -> visible pop")
            self.assertGreaterEqual(to, banners.H,
                                    "stream does not exit below -> visible pop")
            checked += 1
        self.assertGreater(checked, 20)

    def test_matrix_palette_is_hard_identity(self):
        for svg in (self.anim, self.stat):
            self.assertIn(banners.GREEN, svg)          # #00FF41 phosphor
            self.assertIn(banners.BG_0, svg)           # #020604
            self.assertIn(banners.LINE, svg)           # #123D24

    def test_deterministic_output(self):
        self.assertEqual(banners.build(animate=True), self.anim)
        self.assertEqual(banners.build(animate=False), self.stat)

    def test_write_banners_outputs_two_files(self):
        with tempfile.TemporaryDirectory() as tmp:
            written = banners.write_banners(tmp)
            self.assertEqual([os.path.basename(p) for p in written],
                             ["banner.svg", "banner-static.svg"])
            for p in written:
                minidom.parse(p)


# ------------------------------------------------------- snake panel theme --
class ThemeSnakeTests(unittest.TestCase):
    def _write(self, d, content=SNK_FIXTURE, name="snake.svg"):
        p = os.path.join(d, name)
        with open(p, "w", encoding="utf-8") as f:
            f.write(content)
        return p

    def test_injects_panel_and_border(self):
        with tempfile.TemporaryDirectory() as d:
            p = self._write(d)
            theme.theme_file(p, "dark")
            doc = minidom.parse(p)
            root = doc.documentElement
            self.assertEqual(float(root.getAttribute("width")), 824.0)
            self.assertEqual(float(root.getAttribute("height")), 134.0)
            first = [e for e in root.childNodes if e.nodeType == e.ELEMENT_NODE][0]
            self.assertEqual(first.getAttribute("id"), theme.MARK)
            self.assertEqual(first.getAttribute("fill"), "#07110B")
            self.assertEqual(root.getElementsByTagName("rect").length >= 3, True)

    def test_light_variant_gets_stronger_border(self):
        with tempfile.TemporaryDirectory() as d:
            p = self._write(d)
            theme.theme_file(p, "light")
            svg = open(p).read()
            self.assertIn(theme.THEMES["light"]["border"], svg)

    def test_idempotent_no_double_panel(self):
        with tempfile.TemporaryDirectory() as d:
            p = self._write(d)
            theme.theme_file(p, "dark")
            theme.theme_file(p, "dark")
            doc = minidom.parse(p)
            marks = [e for e in doc.getElementsByTagName("rect")
                     if e.getAttribute("id") == theme.MARK]
            self.assertEqual(len(marks), 1)

    def test_viewbox_fallback_when_no_width(self):
        fx = ('<svg xmlns="http://www.w3.org/2000/svg" '
              'viewBox="0 0 300 90"><rect width="10" height="10"/></svg>')
        with tempfile.TemporaryDirectory() as d:
            p = self._write(d, fx)
            theme.theme_file(p, "dark")
            doc = minidom.parse(p)
            first = [e for e in doc.documentElement.childNodes
                     if e.nodeType == e.ELEMENT_NODE][0]
            self.assertEqual(first.getAttribute("width"), "300")

    def test_corrupt_input_fails_and_keeps_file(self):
        with tempfile.TemporaryDirectory() as d:
            p = self._write(d, "<svg><oops>")
            before = open(p).read()
            with self.assertRaises(SystemExit):
                theme.theme_file(p, "dark")
            self.assertEqual(open(p).read(), before)

    def test_input_without_dimensions_fails(self):
        fx = '<svg xmlns="http://www.w3.org/2000/svg"></svg>'
        with tempfile.TemporaryDirectory() as d:
            p = self._write(d, fx)
            with self.assertRaises(SystemExit):
                theme.theme_file(p, "dark")


# ------------------------------------------------------------- stats cards --
class StatsLogicTests(unittest.TestCase):
    def test_aggregate_excludes_forks_consistently(self):
        repos = [
            {"full_name": "o/a", "name": "a", "fork": False, "stargazers_count": 2},
            {"full_name": "o/f", "name": "f", "fork": True, "stargazers_count": 500},
            {"full_name": "o/b", "name": "b", "fork": False, "stargazers_count": 1},
        ]
        fake_langs = {"o/a": {"Python": 10}, "o/b": {"Lua": 5}}
        count, stars, langs, errors = stats.aggregate_repos(
            repos, lambda fn: fake_langs[fn])
        self.assertEqual((count, stars), (2, 3))          # fork star ignored
        self.assertEqual(langs, {"Python": 10, "Lua": 5})  # fork bytes ignored
        self.assertEqual(errors, [])

    def test_aggregate_excludes_listed_vendored_repos(self):
        repos = [
            {"full_name": "o/engine", "name": "engine", "fork": False,
             "stargazers_count": 9},
            {"full_name": "o/mine", "name": "mine", "fork": False,
             "stargazers_count": 1},
        ]
        fake_langs = {"o/engine": {"C": 29000000}, "o/mine": {"Lua": 5}}
        count, stars, langs, errors = stats.aggregate_repos(
            repos, lambda fn: fake_langs[fn],
            excluded=("o/engine",))
        self.assertEqual((count, stars), (1, 1))
        self.assertEqual(langs, {"Lua": 5})

    def test_lang_percentage_denominator_is_total(self):
        rows, other = stats.lang_rows({"A": 60, "B": 30, "C": 10}, top=2)
        self.assertEqual([(r[0], round(r[2], 1)) for r in rows], [("A", 60.0), ("B", 30.0)])
        self.assertEqual(other, 10)

    def test_lang_rows_empty(self):
        rows, other = stats.lang_rows({})
        self.assertEqual((rows, other), ([], 0))

    def test_current_streak(self):
        self.assertEqual(stats.current_streak([0, 0, 3, 1, 0, 2, 2, 0]), 2)
        self.assertEqual(stats.current_streak([0, 0, 0, 3, 1, 2, 2]), 4)
        self.assertEqual(stats.current_streak([0] * 10), 0)
        self.assertIsNone(stats.current_streak(None))
        self.assertEqual(stats.current_streak([]), 0)

    def test_account_age(self):
        created = "2025-03-15T00:00:00Z"
        self.assertEqual(stats.account_age(created, datetime(2026, 10, 23,
                                                             tzinfo=timezone.utc)),
                         "1y 7m")
        self.assertIsNone(stats.account_age(None))

    def test_fmt_val_marks_missing_data(self):
        self.assertEqual(stats.fmt_val(None), "—")
        self.assertEqual(stats.fmt_val(0), "0")     # a real zero stays a zero
        self.assertEqual(stats.fmt_val(12345), "12,345")

    def test_render_cards_atomic_and_valid(self):
        s = {"user": {"public_repos": 4, "followers": 3,
                      "created_at": "2025-03-15T00:00:00Z"},
             "repos": [{"fork": False}] * 4, "langs": {"C#": 70, "Lua & LuaJIT": 30},
             "lang_errors": [], "original_repos": 4, "stars": 2, "commits": 99,
             "streak": 5, "errors": []}
        with tempfile.TemporaryDirectory() as tmp:
            written = stats.render_cards(s, tmp,
                                         datetime(2026, 10, 23, 11, 43,
                                                  tzinfo=timezone.utc))
            self.assertEqual([os.path.basename(p) for p in written],
                             ["github-stats.svg", "top-langs.svg"])
            for p in written:
                self.assertTrue(os.path.exists(p))
                self.assertFalse(os.path.exists(p + ".tmp"))
                doc = minidom.parse(p)          # valid XML
                texts = texts_of(doc)
                self.assertIn("2026-10-23 11:43 UTC", texts)
            # a second render must atomically replace, not append/corrupt
            stats.render_cards(s, tmp)
            for p in written:
                minidom.parse(p)

    def test_escape_of_special_characters(self):
        s = {"user": None, "repos": [], "langs": {}, "lang_errors": [],
             "original_repos": 0, "stars": 0, "commits": None, "streak": None,
             "errors": ["user: simulated outage"]}
        with tempfile.TemporaryDirectory() as tmp:
            stats.render_cards(s, tmp)
            dark = minidom.parse(os.path.join(tmp, "github-stats.svg"))
            texts = texts_of(dark)
            self.assertIn("partial data", texts)
            self.assertIn("—", texts)          # missing values are honest
            self.assertIn(stats.THEME["bg"], dark.toxml())   # Matrix surface
        langs_svg = stats.build_langs_svg(
            {"user": None, "repos": [], "langs": {"X&Y": 5}, "lang_errors": [],
             "original_repos": 0, "stars": 0, "commits": None, "streak": None,
             "errors": []}, "stamp")
        self.assertIn("X&amp;Y", langs_svg)

    def test_paginate_stops_at_short_page(self):
        calls = []

        def fetch_page(p):
            calls.append(p)
            return [{"i": 1}] * (stats.PAGE_SIZE if p == 1 else 3)

        self.assertEqual(len(stats.paginate(fetch_page)), stats.PAGE_SIZE + 3)
        self.assertEqual(calls, [1, 2])

    def test_paginate_respects_cap(self):
        calls = []

        def fetch_page(p):
            calls.append(p)
            return [{"i": 1}] * stats.PAGE_SIZE

        stats.paginate(fetch_page)
        self.assertEqual(calls, list(range(1, stats.MAX_PAGES + 1)))


# ------------------------------------------------- repo reference integrity --
class RepoConsistencyTests(unittest.TestCase):
    """Guard the contract between READMEs, workflows and published files."""

    def read(self, rel):
        with open(os.path.join(ROOT, rel), encoding="utf-8") as f:
            return f.read()

    def test_referenced_local_assets_exist(self):
        for readme in ("README.md", "README.fa.md"):
            srcs = re.findall(r'src="([^"]+?)(?:\?[^"]*)?"', self.read(readme))
            local = [s for s in srcs if not s.startswith("http")]
            self.assertTrue(local, "no local assets referenced in " + readme)
            for s in local:
                self.assertTrue(os.path.exists(os.path.join(ROOT, s)),
                                "%s references missing %s" % (readme, s))

    def test_snake_urls_match_output_branch_files(self):
        for readme in ("README.md", "README.fa.md"):
            txt = self.read(readme)
            self.assertIn("SSSchangerSSS/SSSchangerSSS/output/"
                          "github-contribution-grid-snake.svg?v=", txt)
            self.assertIn("SSSchangerSSS/SSSchangerSSS/output/"
                          "github-contribution-grid-snake-dark.svg?v=", txt)

    def test_snake_workflow_uses_proven_engine_and_matrix_palette(self):
        yml = self.read(".github/workflows/snake.yml")
        self.assertIn("Platane/snk/svg-only@v3", yml)
        for fname in ("dist/github-contribution-grid-snake.svg",
                      "dist/github-contribution-grid-snake-dark.svg"):
            self.assertIn(fname, yml)
        self.assertIn("color_snake=%2300FF41", yml)
        m = re.search(r"color_dots=([\w%,]+)", yml)
        self.assertIsNotNone(m, "color_dots param missing")
        dots = m.group(1).split(",")
        self.assertEqual(len(dots), 5, "snk expects exactly 5 dot colors")
        self.assertIn("theme_snake_svg.py", yml)
        self.assertIn("target_branch: output", yml)

    def test_stats_workflow_tracks_current_card_files(self):
        yml = self.read(".github/workflows/stats.yml")
        self.assertIn("assets/github-stats.svg", yml)
        self.assertIn("assets/top-langs.svg", yml)
        self.assertNotIn("github-stats-light", yml)

    def test_no_secrets_in_repo_text(self):
        pat = re.compile(r"ghp_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,}")
        for base, _, files in os.walk(ROOT):
            if ".git" in base:
                continue
            for f in files:
                if f.rsplit(".", 1)[-1].lower() in ("svg", "yml", "py", "md"):
                    with open(os.path.join(base, f), encoding="utf-8",
                              errors="ignore") as fh:
                        self.assertIsNone(pat.search(fh.read()),
                                          "possible token leak in %s" % f)

    def test_matrix_files_present(self):
        for rel in ("assets/banner.svg", "assets/banner-static.svg",
                    "assets/github-stats.svg", "assets/top-langs.svg",
                    ".github/scripts/make_banners.py",
                    ".github/scripts/theme_snake_svg.py"):
            self.assertTrue(os.path.exists(os.path.join(ROOT, rel)),
                            "missing " + rel)


if __name__ == "__main__":
    unittest.main(verbosity=2)
